local function new(class,props,parent)local inst=Instance.new(class)for k,v in pairs(props)do inst[k]=v end if parent then inst.Parent=parent end return inst end
local function vpart(props,parent)local p=new("Part",{Anchored=true,CanCollide=false,CanQuery=false,CanTouch=false,CastShadow=false,Material=Enum.Material.SmoothPlastic,TopSurface=Enum.SurfaceType.Smooth,BottomSurface=Enum.SurfaceType.Smooth},nil)for k,v in pairs(props)do p[k]=v end p.Parent=parent return p end
local function clamp01(x)return math.clamp(x,0,1)end local function tween(inst,time,props,style,dir)local tw=TS:Create(inst,TweenInfo.new(time,style or Enum.EasingStyle.Quad,dir or Enum.EasingDirection.Out),props)tw:Play()return tw end local function smooth(t)t=clamp01(t)return t*t*(3-2*t)end
local flash=new("Frame",{Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,BorderSizePixel=0,ZIndex=100,Active=false},SG) local function setFlash(a,color)flash.BackgroundColor3=color or Color3.new(1,1,1)flash.BackgroundTransparency=1-clamp01(a)end
local impactFlash={t=-1e9,a=0} local impactShake={t=-1e9,amp=0} local function impactFlashValue()local e=os.clock()-impactFlash.t if e<0 or e>0.62 then return 0 end local rise=math.clamp(e/0.045,0,1)local fall=math.clamp(1-math.max(0,e-0.045)/0.575,0,1)return impactFlash.a*rise*fall*fall end local function impactShakeAmount()local e=os.clock()-impactShake.t if e<0 or e>3.5 then return 0 end return impactShake.amp*(1-e/3.5)^2 end local function shakeCF(cf,amp,t,rotAmp)if amp<=0.001 then return cf end local nx=math.noise(t*23,1.3,0)*2 local ny=math.noise(t*27,5.1,0)*2 local nz=math.noise(t*19,9.7,0)*2 return cf*CFrame.new(nx*amp,ny*amp,0)*CFrame.Angles(ny*rotAmp,nx*rotAmp,nz*rotAmp*0.5)end local wasShaking=false
RunService.RenderStepped:Connect(function()if state~="cinematic"then local f=impactFlashValue()if f>0.003 then setFlash(f)elseif flash.BackgroundTransparency<1 and flash.BackgroundColor3==Color3.new(1,1,1)then setFlash(0)end local hum=player.Character and player.Character:FindFirstChildOfClass("Humanoid")if hum then local a=impactShakeAmount()if a>0.01 then wasShaking=true local t=os.clock()hum.CameraOffset=Vector3.new(math.noise(t*25,1,0),math.noise(t*31,2,0),math.noise(t*17,3,0))*2*a elseif wasShaking then wasShaking=false hum.CameraOffset=Vector3.zero end end end end)
