local caption=new("TextLabel",{AnchorPoint=Vector2.new(0.5,1),Position=UDim2.new(0.5,0,0.9,0),Size=UDim2.new(0.9,0,0,40),BackgroundTransparency=1,Text="",TextColor3=Color3.new(1,1,1),Font=Enum.Font.GothamBold,TextSize=22,TextTransparency=1,TextStrokeTransparency=0.6,ZIndex=95},SG) local function setCaption(text,color)if text==""then tween(caption,0.4,{TextTransparency=1})return end caption.Text=text caption.TextColor3=color or Color3.new(1,1,1)caption.TextTransparency=1 tween(caption,0.4,{TextTransparency=0})end
