local lastDetailUpdate=-1e9 local lastX=-1 local lastRecoil=-1e9 function C.update(x,t)x=clamp01(x or 0)local pulse=0.5+0.5*math.sin(t*(30+x*42))local front=3.4-19.8*clamp01(x*2)local recoil=t>=T.fireT and(1.4*(1-math.exp(-math.max(t-T.fireT,0)*14))*math.exp(-math.max(t-T.fireT,0)*0.8))or 0 if math.abs(recoil-lastRecoil)>0.002 then model:PivotTo(cf*CFrame.new(0,0,recoil*SCALE))lastRecoil=recoil end C.muzzleCF=cf*CFrame.new(0,0,(-19.2+recoil)*SCALE)local updateDetails=(t-lastDetailUpdate)>0.045 or math.abs(x-lastX)>0.012 if updateDetails then lastDetailUpdate=t lastX=x for _,c in ipairs(C.coils)do local z=c.z local wave=math.exp(-((z-front)/0.7)^2)local lit=smooth(clamp01((z-front+0.3)/0.9))*clamp01(x*2)local awake=0.08+0.10*(0.5+0.5*math.sin(t*2+c.k*0.32))local glow=clamp01(awake+lit*0.72+wave*0.7+(t>=T.fireT and 0.5*math.exp(-(t-T.fireT)*5)or 0))local tone=METAL_DARK:Lerp(METAL,0.25+glow*0.70)for _,p in ipairs(c.main)do p.Color=tone end for _,p in ipairs(c.inner)do p.Color=RED:Lerp(HOT,clamp01(wave*0.75+lit*0.4))p.Transparency=0.56-0.50*glow end for _,p in ipairs(c.groove)do p.Color=RED:Lerp(HOT,clamp01(wave*0.88+lit*0.26))p.Transparency=0.72-0.63*clamp01(wave+lit*0.6)end for _,p in ipairs(c.clamps)do p.Color=METAL_DARK:Lerp(GOLD_LIT,clamp01(wave*0.24+lit*0.12))end end for _,railGroup in ipairs(C.railSegments)do for _,p in ipairs(railGroup.parts)do local localZ=cf:PointToObjectSpace(p.Position).Z/SCALE local wave=math.exp(-((localZ-front)/0.95)^2)local lit=smooth(clamp01((localZ-front+0.3)/1.0))*clamp01(x*2)p.Color=RED:Lerp(HOT,clamp01(wave*0.95+lit*0.24))p.Transparency=0.76-0.65*clamp01(wave+lit*0.8)end end for _,p in ipairs(C.emitterParts)do p.Color=RED:Lerp(HOT,clamp01(x*0.75+pulse*0.2))p.Transparency=0.38-0.30*x end end local radius=0.12+x^1.2*1.55*(0.9+0.1*pulse)C.orb.Size=Vector3.one*(radius*2*SCALE)C.orb.Color=RED:Lerp(HOT,clamp01(x*x*0.9+pulse*x*0.2))C.orbLight.Brightness=0.2+x*x*12 C.orbLight.Range=45+x*190 C.lens.Color=RED:Lerp(HOT,clamp01(x*0.95+pulse*x*0.15))C.lens.Transparency=0.28-0.24*x C.reactorLight.Brightness=0.4+1.8*x end return C end
